class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        int best = 0;

        for (int l = 0; l < n; l++) {
            // 剪枝：即使右边全部用得上，也超不过当前最优
            if ((long) heights[l] * (n - l) <= best) continue;

            int minH = heights[l];
            for (int r = l; r < n; r++) {
                minH = Math.min(minH, heights[r]);   // 边扩边维护
                best = Math.max(best, minH * (r - l + 1));
            }
        }
        return best;
    }
}

class Solution {
    public int largestRectangleArea(int[] heights) {
        if (heights == null || heights.length == 0) return 0;
        return solve(heights, 0, heights.length - 1);
    }

    private int solve(int[] h, int lo, int hi) {
        if (lo > hi) return 0;

        // 找区间内最矮柱子的下标
        int m = lo;
        for (int i = lo; i <= hi; i++) {
            if (h[i] < h[m]) m = i;
        }

        int cross = h[m] * (hi - lo + 1);   // 跨越最矮柱子
        int left = solve(h, lo, m - 1);
        int right = solve(h, m + 1, hi);
        return Math.max(cross, Math.max(left, right));
    }
}

import java.util.*;

class Solution {
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        // 首尾补 0 当哨兵
        int[] arr = new int[n + 2];
        for (int i = 0; i < n; i++) arr[i + 1] = heights[i];

        Deque<Integer> stack = new ArrayDeque<>();   // 存下标，高度递增
        int best = 0;

        for (int i = 0; i < arr.length; i++) {
            // 当前柱子比栈顶矮：栈顶的右边界确定，弹出并结算
            while (!stack.isEmpty() && arr[stack.peek()] > arr[i]) {
                int h = arr[stack.pop()];
                int left = stack.peek();     // 首哨兵保证栈不会空
                best = Math.max(best, h * (i - left - 1));
            }
            stack.push(i);
        }
        return best;   // 尾哨兵已把栈清空，无需额外循环
    }
}
